package dev.lunna.daiana4j.protocol.in;

import dev.lunna.daiana4j.protocol.OpCodes;
import dev.lunna.daiana4j.util.UuidUtil;
import io.netty.buffer.ByteBuf;
import org.jetbrains.annotations.NotNull;

import java.util.UUID;

import static java.util.Objects.requireNonNull;

/**
 * Inbound packet containing a generated temporary room join code from the server (Opcode 0x04).
 *
 * @param code the temporary room {@link UUID} generated by the server
 */
public record TempCodeResponse(@NotNull UUID code) implements WsInPacket {

    /**
     * Compact constructor validating non-null arguments.
     *
     * @param code the temporary room {@link UUID} generated by the server
     */
    public TempCodeResponse {
        requireNonNull(code, "code cannot be null");
    }

    @Override
    public @NotNull OpCodes.Server2Client opCode() {
        return OpCodes.Server2Client.TEMP_CODE_RESPONSE;
    }

    /**
     * Deserializes a {@link TempCodeResponse} packet from a {@link ByteBuf}.
     *
     * @param buf the buffer to read from
     * @return the deserialized {@link TempCodeResponse} packet
     */
    @NotNull
    public static TempCodeResponse fromByteBuf(@NotNull final ByteBuf buf) {
        return new TempCodeResponse(UuidUtil.fromByteBuf(buf));
    }
}
